static void text_field(const char *json,const char *key,char *out,size_t n)
{yyjson_doc *d=yyjson_read(json,strlen(json),0);const char *s=d?yyjson_get_str(yyjson_obj_get(yyjson_doc_get_root(d),key)):NULL;strcpy_s(out,n,s?s:"");yyjson_doc_free(d);}
