static void refresh(void)
{char *json=NULL;CHECK(ui_ai_edit_get_state(service,&json)==UI_STATUS_OK);if(json){CHECK(strlen(json)<sizeof(state));strcpy_s(state,sizeof(state),json);ui_ai_release(json);}}
static void pump(void)
{MSG m;unsigned n=0;while(n++<128&&PeekMessageW(&m,NULL,0,0,PM_REMOVE)){if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);}}ui_workspace_poll(workspace);CHECK(ui_ai_service_poll(service,64)==UI_STATUS_OK);refresh();(void)MsgWaitForMultipleObjects(0,NULL,FALSE,1,QS_ALLINPUT);}
static int wait_phase(int wanted)
{DWORD start=GetTickCount();do{pump();if(integer(state,"phase")==wanted)return 1;}while(GetTickCount()-start<5000);fprintf(stderr,"state %.1600s\n",state);return 0;}
static int read_model(const char *cap,const char *params)
{ui_cap_target_t t={0};ui_cap_result_t result={0};uint64_t call=0;ui_status_t status;t.size=sizeof(t);t.version=1;status=ui_capability_bind(app.host,resource,&t);if(status)return 0;status=ui_capability_prepare(app.host,cap,&t,params,&call);if(status)return 0;status=ui_capability_dispatch(app.host,call);if(status){(void)ui_capability_forget(app.host,call);return 0;}result.size=sizeof(result);result.version=1;status=ui_capability_get_result(app.host,call,&result);if(!status&&result.outcome==UI_CAP_OK&&result.output_json){CHECK(strlen(result.output_json)<sizeof(document));strcpy_s(document,sizeof(document),result.output_json);}else status=UI_STATUS_VALIDATION_FAILED;CHECK(ui_capability_forget(app.host,call)==UI_STATUS_OK);return status==UI_STATUS_OK;}
