static ui_status_t collect(const ui_cap_ui_context_t *c,char *out,size_t capacity,size_t *length,void *data)
{(void)c;(void)data;*length=strlen(manual_params);if(*length>=capacity)return UI_STATUS_LIMIT_EXCEEDED;memcpy(out,manual_params,*length+1);return UI_STATUS_OK;}
static void notice(const ui_cap_ui_notice_t *n,void *data){(void)data;if(n->call_id)manual_call=n->call_id;}
